defmodule StrangertalksNew.EmojiValidator do
  @moduledoc """
  Validates and canonicalizes Unicode RGI emoji reaction inputs according to the pinned
  Unicode 17.0 / Emojibase dataset.

  Guarantees:
  - Canonical identity: Maps all accepted emoji variants (e.g. unqualified vs VS16 fully-qualified)
    to exactly one deterministic canonical Unicode string.
  - Byte bound: Rejects any input exceeding 64 UTF-8 bytes before processing.
  - Safe memory: Zero dynamic atom allocation.
  - Canonical removal: `nil` is strictly validated and normalized as `nil`.
  """

