  @doc """
  Returns the maximum allowed byte size for a single emoji reaction sequence (64 bytes).
  """
  def max_emoji_bytes, do: @max_emoji_bytes

  @doc """
  Validates and canonicalizes an input reaction.

  Returns `{:ok, canonical_emoji_string}` for a valid Unicode emoji,
  `{:ok, nil}` for reaction removal (`nil`),
  or `{:error, :invalid_reaction}` for unsupported/malformed input.
  """
  def canonical_reaction(nil), do: {:ok, nil}

  def canonical_reaction(emoji) when is_binary(emoji) do
    if byte_size(emoji) <= @max_emoji_bytes do
      case Map.fetch(@canonical_map, emoji) do
        {:ok, canonical} -> {:ok, canonical}
        :error -> {:error, :invalid_reaction}
      end
    else
      {:error, :invalid_reaction}
    end
  end

  def canonical_reaction(_), do: {:error, :invalid_reaction}

  @doc """
  Checks whether an emoji reaction sequence or nil is valid.
  """
  def valid_reaction?(emoji) do
    match?({:ok, _}, canonical_reaction(emoji))
  end

  @doc """
  Returns the canonical Unicode sequence for a valid emoji, or raises if invalid.
  """
  def canonical_reaction!(nil), do: nil

  def canonical_reaction!(emoji) when is_binary(emoji) do
    case canonical_reaction(emoji) do
      {:ok, canonical} ->
        canonical

      {:error, :invalid_reaction} ->
        raise ArgumentError, "Invalid emoji reaction: " <> inspect(emoji)
    end
  end
end
